package main
import "fmt"
func main() {
    var n int
    fmt.Scan(&n)
    solteiros := make(map[int]int)
    casais := 0

    for i := 0 ; i < n ; i++ {
        var especie int
        fmt.Scan(&especie)
        if solteiros[-especie] > 0 {
            solteiros[-especie]--
            casais++

        } else {
            solteiros[especie]++
        }
    }
    fmt.Println(casais)
}
